<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$type=($_POST['return_type']??'sale')==='purchase'?'purchase':'sale';$bid=(int)($_POST['batch_id']??0);$qty=max(1,(int)($_POST['quantity']??0));$b=$db->prepare('SELECT * FROM batches WHERE id=?');$b->execute([$bid]);$b=$b->fetch();if(!$b)throw new RuntimeException('Batch not found.');if($type==='purchase' && (int)$b['units_remaining']<$qty)throw new RuntimeException('Not enough stock for purchase return.');$db->beginTransaction();$new=$type==='sale'?(int)$b['units_remaining']+$qty:(int)$b['units_remaining']-$qty;$db->prepare('UPDATE batches SET units_remaining=? WHERE id=?')->execute([$new,$bid]);$amount=$qty*(float)$b['purchase_unit_cost'];$db->prepare('INSERT INTO returns(return_type,medicine_id,batch_id,quantity_units,amount,note) VALUES(?,?,?,?,?,?)')->execute([$type,$b['medicine_id'],$bid,$qty,$amount,trim($_POST['note']??'')]);$movement=$type==='sale'?$qty:-$qty;$db->prepare("INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,note) VALUES(?,?, 'return',?,?)")->execute([$b['medicine_id'],$bid,$movement,ucfirst($type).' return']);$db->commit();header('Location: returns.php?saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}} $batches=$db->query('SELECT b.*,m.name FROM batches b JOIN medicines m ON m.id=b.medicine_id ORDER BY m.name,b.expiry_date')->fetchAll();$rows=$db->query("SELECT r.*,m.name,b.batch_no FROM returns r JOIN medicines m ON m.id=r.medicine_id LEFT JOIN batches b ON b.id=r.batch_id ORDER BY r.id DESC LIMIT 100")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Returns</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">RETURNS</div><h1>Returns</h1><p>Record sale returns or send received stock back to a supplier.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Return recorded and stock adjusted.</div><?php endif;?><section class="panel"><h2>New Return</h2><form method="post" class="grid"><label>Type<select name="return_type"><option value="sale">Customer / Sale Return (adds stock)</option><option value="purchase">Supplier / Purchase Return (removes stock)</option></select></label><label>Batch<select name="batch_id" required><option value="">Select batch</option><?php foreach($batches as $b):?><option value="<?=$b['id']?>"><?=e($b['name'])?> · <?=e($b['batch_no']??'No batch')?> · <?=number_format((int)$b['units_remaining'])?> units</option><?php endforeach;?></select></label><label>Quantity (tablets)<input name="quantity" type="number" min="1" required></label><label>Note<input name="note"></label><button class="btn">Save Return</button></form></section><section class="panel"><table><tr><th>Type</th><th>Medicine</th><th>Batch</th><th>Units</th><th>Amount</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e(ucfirst($r['return_type']))?></td><td><?=e($r['name'])?></td><td><?=e($r['batch_no']??'—')?></td><td><?=number_format((int)$r['quantity_units'])?></td><td>Rs. <?=money((float)$r['amount'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></section></main></body></html>